/* Byte-level conformance test for the BP++ transcript (src/bppp_transcript.c)
 * against vectors generated by the Rust reference implementation of the
 * specification. The vectors use small multiples of the base
 * point as stand-ins for the prover's messages; the generators are
 * mpt-crypto's own (G = base point, G_i = NUMS("G", i), H_i = NUMS("H", i)).
 * Regenerate the table from the reference implementation if the transcript
 * changes. */
#include "../src/bppp_transcript.h"
#include "secp256k1_mpt.h"
#include "test_utils.h"
#include <secp256k1.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

